internal val LOCALE_DISPLAY_NAMES_SHN: String =
    "root\u001Faa\u001Dဢႃးၾႃႇ\u001Eab\u001Dဢပ်ႇၶႃးၸီႇယႅၼ်ႇ\u001Eaf\u001Dဢၾရိၵၢၼ်း\u001Eagq\u001Dဢၵ်ႉႁဵမ်\u001Eak\u001Dဢႃးၵၼ်ႇ\u001Eam\u001Dဢမ်ႇႁႄးရိၵ်ႉ\u001Ean\u001Dဢရၵၼိတ်ႉ\u001Eann\u001Dဢူဝ်ႇပူဝ်ႇလူဝ်ႇ\u001Eapc\u001Dလႄႇဝၼ်ႇတိၼ်း ဢႃႇရၢပ်ႉ\u001Ear\u001Dဢႃႇရၢပ်ႈ\u001Ear_001\u001Dလၵ်းၸဵင် ဢႃႇရၢပ်ႈ ပၢၼ်မႂ်ႇ\u001Earn\u001Dမပူးၶျီႇ\u001Eas\u001Dဢႃႇသမ်ႇ\u001Easa\u001Dဢသူး\u001East\u001Dဢတိူဝ်ႇရီႇယႅၼ်ႇ\u001Eaz\u001Dဢႃႇၸႃႇပၢႆႇၸၼ်ႇ\u001Eaz#short\u001Dဢႃႇၸႃႇပၢႆႇၸၼ်ႇ\u001Eba\u001Dပၢတ်ႇသျ်ၵေးသ်\u001Ebal\u001Dပလူးၶျီႇ\u001Ebas\u001Dပႃးသႃႇ\u001Ebe\u001Dပႄႇလႃႇရုတ်ႈ\u001Ebem\u001Dပႅမ်ႇပႃႇ\u001Ebew\u001Dပႅတ်ႉထဝီႇ\u001Ebez\u001Dပႅၼ်းၼႃႈ\u001Ebg\u001Dပူႇၵႃႇရီႇယႃႇ\u001Ebgc\u001Dႁႃႇယၼ်ႇဝီႇ\u001Ebgn\u001Dပလူးၶျီႇ ပွတ်းတူၵ်း\u001Ebho\u001Dပူဝ်ႉၵျ်ပူႇရီႇ\u001Eblo\u001Dဢႃးၼီႈ\u001Eblt\u001Dတႆးလမ်\u001Ebm\u001Dပႅမ်ပႃရႃႇ\u001Ebn\u001Dပင်းၵလႃႇ\u001Ebo\u001Dထိပႅတ်ႉ\u001Ebqi\u001Dပၵ်းထီႇဢႃးရီႇ\u001Ebr\u001Dပရႅတ်ႉတၼ်ႇ\u001Ebrx\u001Dပူဝ်တူဝ်\u001Ebs\u001Dပေႃးသၼီးယႃး\u001Ebss\u001Dဢၵ်ႉၶူးသ်\u001Ebua\u001Dပိူဝ်းယႅတ်ႇ\u001Ebyn\u001Dပလိၼ်ႇ\u001Eca\u001Dၶႅတ်ႇတလၼ်ႇ\u001Ecad\u001Dၶႅတ်ႇတူဝ်း\u001Ecch\u001Dဢႅတ်ႉသမ်ႇ\u001Eccp\u001Dၶျၵ်ႉမႃး\u001Ece\u001Dၶျႅတ်ႉၶျႅၼ်ႇ\u001Eceb\u001Dသိုပ်ႇပႂႃးၼူဝ်ႇ\u001Ecgg\u001Dၶျီၵႃႇ\u001Echo\u001Dၶျွၵ်ႉတေႃႇ\u001Echr\u001Dၶျေရၵီႇ\u001Ecic\u001Dၶျိၵ်ႉၵသေႃး\u001Eckb\u001Dၶိူဝ်းတိတ်ႉသျ် ပွတ်းၵၢင်\u001Eco\u001Dၵေႃသီၵၼ်ႇ\u001Ecop\u001Dၶွပ်းထိၵ်ႇ\u001Ecs\u001Dၶျႅၵ်ႈ\u001Ecsw\u001Dသွမ်ႇပီႇၶရိ\u001Ecu\u001Dၶျၢတ်ႉသလႃးဝိၵ်ႉ\u001Ecv\u001Dၶျူးဝၢတ်ႇ\u001Ecy\u001Dဝႄးလ်သျ်\u001Eda\u001Dတေးၼိတ်ႉသျ်\u001Edav\u001Dတၢႆးတႃႇ\u001Ede\u001Dၵျႃႇမၼ်ႇ\u001Ede_AT\u001Dၵျႃႇမၼ်ႇ (ဢေႃးသထရီးယႃး)\u001Ede_CH\u001Dၵျႃႇမၼ်ႇ (သဝိတ်ႈၸႃႇလႅၼ်ႇ)\u001Edje\u001Dၸႃမႃႇ\u001Edoi\u001Dတွၵ်ႉၵရိပ်ႉ\u001Edsb\u001Dလူဝ်းဝႃးသေႃႇပီႇယႅၼ်ႇ\u001Edua\u001Dတူးဝႃးလႃႇ\u001Edv\u001Dတီႇဝႄးႁီႇ\u001Edyo\u001Dၵျူဝ်လႃ-ၾူင်းၼီႇ\u001Edz\u001Dၸွင်းၵႃႇ\u001Eebu\u001Dဢႅမ်းပူး\u001Eee\u001Dယူး\u001Eel\u001Dၵရိတ်ႈ\u001Een\u001Dဢိင်းၵလဵတ်ႈ\u001Een_AU\u001Dဢိင်းၵလဵတ်ႈ (ဢေႃႉသထရေးလီးယႃး)\u001Een_CA\u001Dဢိင်းၵလဵတ်ႈ (ၶႅၼ်ႇၼေႇတႃႇ)\u001Een_GB\u001Dဢိင်းၵ